<?php
namespace App\Http\Middleware;use App\Domain\ApiHub\Models\{TenantApiKey,TenantApiQuotaPolicy,TenantApiUsageEvent};use App\Domain\Network\Billing\{EntitlementService,SubscriptionService};use Closure;use Illuminate\Http\Request;use Illuminate\Support\Facades\RateLimiter;
final class AuthenticateTenantApiV1{public function handle(Request$r,Closure$next){if(!config('zigo_api_hub.enabled'))return$this->error($r,'API_UNAVAILABLE','API Hub no está habilitado.',503);$plain=$r->bearerToken();if(!$plain)return$this->error($r,'INVALID_API_KEY','Proporciona una API key Bearer válida.',401);$key=TenantApiKey::with('client.tenant')->where('key_hash',hash('sha256',$plain))->first();if(!$key||$key->revoked_at||($key->expires_at&&$key->expires_at->isPast())||!$key->client||$key->client->status!=='ACTIVE')return$this->error($r,'INVALID_API_KEY','La API key no es válida o está inactiva.',401);$tenant=$key->client->tenant;if(!$tenant||$tenant->status!=='active'||!app(SubscriptionService::class)->activeForTenant($tenant))return$this->error($r,'SUBSCRIPTION_REQUIRED','La suscripción del tenant no está operativa.',403);if(!app(EntitlementService::class)->has($tenant,'API'))return$this->error($r,'API_ENTITLEMENT_REQUIRED','El tenant no tiene API Hub activo.',403);$policy=TenantApiQuotaPolicy::current($tenant->id);$limit=$policy?->monthly_request_limit??config('zigo_api_hub.default_monthly_limit');$used=TenantApiUsageEvent::where('tenant_id',$tenant->id)->where('occurred_at','>=',now()->startOfMonth())->sum('units');if($used>=$limit)return$this->quota($r,$limit,$used);$perMinute=$policy?->rate_limit_per_minute??config('zigo_api_hub.default_rate_limit');$rateKey='zigo-api-v1:'.$key->id;if(RateLimiter::tooManyAttempts($rateKey,$perMinute)){return$this->error($r,'API_RATE_LIMIT_EXCEEDED','Demasiadas solicitudes.',429)->withHeaders(['Retry-After'=>RateLimiter::availableIn($rateKey)]);}RateLimiter::hit($rateKey,60);$key->update(['last_used_at'=>now()]);$key->client->update(['last_used_at'=>now()]);foreach(['tenant'=>$tenant,'api_client'=>$key->client,'api_key'=>$key,'api_scopes'=>$key->scopes??[],'api_quota_policy'=>$policy,'api_quota_limit'=>$limit,'api_quota_used'=>$used]as$n=>$v)$r->attributes->set($n,$v);$response=$next($r);$response->headers->set('X-ZIGO-Quota-Limit',(string)$limit);$response->headers->set('X-ZIGO-Quota-Remaining',(string)max(0,$limit-$used-($response->isSuccessful()?1:0)));$response->headers->set('X-ZIGO-Quota-Reset',now()->endOfMonth()->toIso8601String());return$response;}
 private function quota(Request$r,int$limit,int$used){return$this->error($r,'API_QUOTA_EXCEEDED','La cuota mensual fue agotada.',429)->withHeaders(['X-ZIGO-Quota-Limit'=>$limit,'X-ZIGO-Quota-Remaining'=>0,'X-ZIGO-Quota-Reset'=>now()->endOfMonth()->toIso8601String()]);}private function error(Request$r,string$code,string$message,int$status){return response()->json(['error'=>['code'=>$code,'message'=>$message],'meta'=>['request_id'=>$r->attributes->get('zigo_request_id')]],$status);}}
